// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(uint256 amount, address funder) public {
        vm.assume(funder != address(c));
        amount = bound(amount, 2, 10 ether);
        vm.deal(funder, amount);
        vm.prank(funder);
        (bool ok,) = address(c).call{value: amount}("");
        assertTrue(ok);

        vm.prank(address(this));
        c.withdrawAll();

        assertTrue(address(c).balance == 0);
    }
}
